147: function drawSun(sun, now) {
148:   const age = now - sun.spawnedAt;
149:   const fadeIn = Math.min(1, age / SUN_CONFIG.spawnFadeMs);
150:   let alpha = fadeIn;
151:   let scale = 1;
152:   let lift = 0;
153:   if (sun.collected) {
154:     const progress = Math.min(1, (now - sun.collectedAt) / SUN_CONFIG.collectDurationMs);
155:     alpha *= 1 - progress;
156:     scale = 1 + progress * .65;
157:     lift = progress * 24;
158:   } else if (sun.expired) {
159:     alpha *= Math.max(0, 1 - (now - sun.expiredAt) / 300);
160:   }
161:   const hovered = pointer.hoveredSun === sun.id && !sun.collected && !sun.expired;
162:   const radius = SUN_CONFIG.radius * (hovered ? 1.12 : 1) * scale;
163:   const sway = Math.sin(now * .0024 + sun.phase) * (sun.falling ? 2.8 : 1.7);
164:   const pulse = 1 + Math.sin(now * .004 + sun.phase) * .045;
165:   const x = sun.x + sway;
166:   const y = sun.y - lift + Math.sin(now * .0018 + sun.phase) * 1.5;
167:   ctx.save();
168:   ctx.globalAlpha = Math.max(0, alpha);
169:   ctx.translate(x, y);
170:   ctx.scale(pulse, pulse);
171:   ctx.shadowColor = hovered ? "rgba(255,244,95,.95)" : "rgba(255,203,48,.72)";
172:   ctx.shadowBlur = hovered ? 24 : 15;
173:   ctx.fillStyle = "rgba(255,218,74,.25)";
174:   ctx.beginPath(); ctx.arc(0, 0, radius + 5, 0, Math.PI * 2); ctx.fill();
175:   ctx.shadowBlur = 0;
176:   ctx.rotate(now * .00035 + sun.phase);
177:   ctx.lineCap = "round";
178:   for (let i = 0; i < 12; i++) {
179:     ctx.save(); ctx.rotate(i * Math.PI / 6);
180:     ctx.strokeStyle = i % 2 ? "#e89a23" : "#d9851d";
181:     ctx.lineWidth = 3.2;
182:     ctx.beginPath(); ctx.moveTo(0, -radius * .78); ctx.lineTo(0, -radius - (i % 3 === 0 ? 9 : 7)); ctx.stroke();
183:     ctx.restore();
184:   }
185:   const gradient = ctx.createRadialGradient(-radius * .32, -radius * .38, 1, 0, 0, radius);
186:   gradient.addColorStop(0, "#fffeb0"); gradient.addColorStop(.52, "#ffe35a"); gradient.addColorStop(1, "#f6ad2e");
187:   ctx.beginPath(); ctx.arc(0, 0, radius, 0, Math.PI * 2);
188:   ctx.fillStyle = gradient; ctx.fill(); ctx.lineWidth = 2.2; ctx.strokeStyle = "#d68520"; ctx.stroke();
189:   ctx.beginPath(); ctx.arc(0, 0, radius * .57, 0, Math.PI * 2);
190:   ctx.fillStyle = "rgba(255,249,139,.68)"; ctx.fill();
191:   ctx.beginPath(); ctx.ellipse(-radius * .28, -radius * .34, radius * .22, radius * .12, -.55, 0, Math.PI * 2);
192:   ctx.fillStyle = "rgba(255,255,225,.84)"; ctx.fill();
193:   if (hovered) {
194:     ctx.beginPath(); ctx.arc(0, 0, radius + 12, 0, Math.PI * 2);
195:     ctx.setLineDash([3, 4]); ctx.lineWidth = 1.5; ctx.strokeStyle = "rgba(255,255,207,.9)"; ctx.stroke(); ctx.setLineDash([]);
196:   }
197:   ctx.restore();
198: }
