247:     ctx.fillStyle = "rgba(41,43,29,.48)"; ctx.fillRect(x + 4, y + 4, w - 8, (h - 8) * (1 - progress));
248:     ctx.fillStyle = "#fff6cf"; ctx.font = "900 13px Trebuchet MS, sans-serif"; ctx.textAlign = "center";
249:     ctx.fillText(`${(remaining / 1000).toFixed(1)} s`, x + w * .67, y + h * .68);
