287: function updateCombat(now) {
288:   const { left, top, cellW, cellH } = layout;
289:   const targets = [...enemies.enemies.values()].filter((enemy) => enemy.alive);
290:   for (const plant of game.plants.values()) {
291:     if (!plant.alive || !plant.exists) {
292:       plant.attackState = "IDLE";
293:       plant.targetId = null;
294:       continue;
295:     }
296:     plant.boardX = (plant.worldPosition.x - left) / cellW;
297:     const target = targets
298:       .filter((enemy) => enemy.row === plant.row && enemy.x > plant.boardX)
299:       .sort((a, b) => a.x - b.x)[0] ?? null;
300:     plant.targetId = target?.id ?? null;
301:     if (!target) {
302:       plant.attackState = "IDLE";
303:       continue;
304:     }
305:     if (now >= plant.nextAttackAt) {
306:       const plantSize = cellW * .83;
307:       projectiles.spawn({
308:         x: plant.worldPosition.x + plantSize * .39,
309:         y: plant.worldPosition.y - plantSize * .565,
310:         row: plant.row,
311:         damage: plant.damage,
312:         speed: plant.projectileSpeed,
313:         ownerId: plant.id,
314:       }, now);
315:       plant.attackState = "SHOOTING";
316:       plant.attackStartedAt = now;
317:       plant.nextAttackAt = now + plant.attackIntervalMs;
318:     } else {
319:       plant.attackState = now - plant.attackStartedAt < 180 ? "SHOOTING" : "AIMING";
320:     }
321:   }
322:   projectiles.update(now, enemies.enemies, { ...layout, width, left, top, cellW, cellH }, enemies);
323: }
