340: function drawBoard(now) {
341:   const { left, top, cellW, cellH, boardW, boardH } = layout;
342:   ctx.save();
343:   ctx.shadowColor = "rgba(46,66,34,.28)"; ctx.shadowBlur = 16; ctx.shadowOffsetY = 8;
344:   fillRound(ctx, left - 12, top - 12, boardW + 24, boardH + 24, 16, "#a96e39", "#754a2c", 3);
345:   ctx.shadowColor = "transparent";
346:   const frame = ctx.createLinearGradient(0, top - 12, 0, top + boardH + 12);
347:   frame.addColorStop(0, "#d49a55"); frame.addColorStop(.5, "#bd7f41"); frame.addColorStop(1, "#99602f");
348:   fillRound(ctx, left - 8, top - 8, boardW + 16, boardH + 16, 11, frame, "#e4b46f", 2);
349:   // These cells are the sole source of row/column hit-testing and occupancy visuals.
350:   for (let row = 0; row < game.rows; row++) {
351:     for (let column = 0; column < game.columns; column++) {
352:       const x = left + column * cellW; const y = top + row * cellH;
353:       const plant = game.getAt(row, column);
354:       const hovered = state.hoveredCell?.row === row && state.hoveredCell?.column === column;
355:       const shade = (row + column) % 2 === 0;
356:       fillRound(ctx, x + 1, y + 1, cellW - 2, cellH - 2, 4, shade ? "#88c750" : "#7fbd48", "rgba(49,101,39,.33)", 1);
357:       ctx.strokeStyle = "rgba(238,255,177,.15)"; ctx.lineWidth = 1;
358:       ctx.beginPath(); ctx.moveTo(x + 6, y + cellH - 6); ctx.lineTo(x + cellW - 7, y + 7); ctx.stroke();
359:       if (state.selected) {
360:         ctx.fillStyle = plant ? "rgba(193,61,44,.20)" : "rgba(220,255,161,.15)";
361:         ctx.fillRect(x + 2, y + 2, cellW - 4, cellH - 4);
362:         ctx.strokeStyle = plant ? "rgba(163,48,38,.68)" : "rgba(242,255,193,.8)";
363:         ctx.lineWidth = plant ? 2 : 1.3; ctx.setLineDash(plant ? [4, 3] : [5, 5]);
364:         ctx.strokeRect(x + 4, y + 4, cellW - 8, cellH - 8); ctx.setLineDash([]);
365:       }
366:       if (hovered) {
367:         ctx.strokeStyle = state.selected && plant ? "#cf5141" : "#fff39a";
368:         ctx.lineWidth = 3; ctx.strokeRect(x + 3, y + 3, cellW - 6, cellH - 6);
369:       }
370:     }
371:   }
372:   ctx.restore();
373: 
374:   // Plant data is rendered independently from occupancy and placement rules.
375:   for (const plant of game.plants.values()) {
376:     if (!plant.exists) continue;
377:     const target = plant.targetId ? enemies.get(plant.targetId) : null;
378:     const plantSize = cellW * .83;
379:     const muzzleX = plant.worldPosition.x + plantSize * .39;
