108: function makeLayout() {
109:   const compact = width < 600;
110:   const short = height < 500;
111:   const cellW = compact ? Math.min(60, (width - 28) / 9) : Math.min(105, (width - 100) / 9);
112:   const gridTop = compact ? (short ? 124 : 148) : (short ? 116 : 224);
113:   const cellH = Math.max(34, Math.min(compact ? 65 : 94, cellW * (compact ? 1.0 : .92), (height - gridTop - 34) / 5));
114:   const boardW = cellW * 9;
115:   const boardH = cellH * 5;
116:   return {
117:     compact, short, cellW, cellH, boardW, boardH,
118:     left: (width - boardW) / 2,
119:     top: gridTop,
120:     card: compact ? { x: 12, y: short ? 26 : 34, w: 154, h: 91 } : { x: 34, y: short ? 10 : 80, w: 220, h: 122 },
121:     counter: compact ? { x: 176, y: short ? 28 : 36, w: Math.max(106, width - 190), h: 48 } : { x: 275, y: short ? 17 : 91, w: 188, h: 66 },
122:   };
