211: function drawSun(sun, now) {
212:   const age = now - sun.spawnedAt;
213:   const fadeIn = Math.min(1, age / SUN_CONFIG.spawnFadeMs);
214:   let alpha = fadeIn;
215:   let scale = 1;
216:   let lift = 0;
217:   if (sun.collected) {
218:     const progress = Math.min(1, (now - sun.collectedAt) / SUN_CONFIG.collectDurationMs);
219:     alpha *= 1 - progress;
220:     scale = 1 + progress * .65;
221:     lift = progress * 24;
222:   } else if (sun.expired) {
223:     alpha *= Math.max(0, 1 - (now - sun.expiredAt) / 300);
224:   }
225:   const hovered = pointer.hoveredSun === sun.id && !sun.collected && !sun.expired;
226:   const radius = SUN_CONFIG.radius * (hovered ? 1.12 : 1) * scale;
227:   const sway = Math.sin(now * .0024 + sun.phase) * (sun.falling ? 2.8 : 1.7);
228:   const pulse = 1 + Math.sin(now * .004 + sun.phase) * .045;
229:   const x = sun.x + sway;
230:   const y = sun.y - lift + Math.sin(now * .0018 + sun.phase) * 1.5;
231:   ctx.save();
232:   ctx.globalAlpha = Math.max(0, alpha);
233:   ctx.translate(x, y);
234:   ctx.scale(pulse, pulse);
235:   ctx.shadowColor = hovered ? "rgba(255,244,95,.95)" : "rgba(255,203,48,.72)";
236:   ctx.shadowBlur = hovered ? 24 : 15;
237:   ctx.fillStyle = "rgba(255,218,74,.25)";
238:   ctx.beginPath(); ctx.arc(0, 0, radius + 5, 0, Math.PI * 2); ctx.fill();
239:   ctx.shadowBlur = 0;
240:   ctx.rotate(now * .00035 + sun.phase);
241:   ctx.lineCap = "round";
242:   for (let i = 0; i < 12; i++) {
243:     ctx.save(); ctx.rotate(i * Math.PI / 6);
244:     ctx.strokeStyle = i % 2 ? "#e89a23" : "#d9851d";
245:     ctx.lineWidth = 3.2;
246:     ctx.beginPath(); ctx.moveTo(0, -radius * .78); ctx.lineTo(0, -radius - (i % 3 === 0 ? 9 : 7)); ctx.stroke();
247:     ctx.restore();
248:   }
249:   const gradient = ctx.createRadialGradient(-radius * .32, -radius * .38, 1, 0, 0, radius);
250:   gradient.addColorStop(0, "#fffeb0"); gradient.addColorStop(.52, "#ffe35a"); gradient.addColorStop(1, "#f6ad2e");
251:   ctx.beginPath(); ctx.arc(0, 0, radius, 0, Math.PI * 2);
252:   ctx.fillStyle = gradient; ctx.fill(); ctx.lineWidth = 2.2; ctx.strokeStyle = "#d68520"; ctx.stroke();
253:   ctx.beginPath(); ctx.arc(0, 0, radius * .57, 0, Math.PI * 2);
254:   ctx.fillStyle = "rgba(255,249,139,.68)"; ctx.fill();
255:   ctx.beginPath(); ctx.ellipse(-radius * .28, -radius * .34, radius * .22, radius * .12, -.55, 0, Math.PI * 2);
256:   ctx.fillStyle = "rgba(255,255,225,.84)"; ctx.fill();
257:   if (hovered) {
258:     ctx.beginPath(); ctx.arc(0, 0, radius + 12, 0, Math.PI * 2);
259:     ctx.setLineDash([3, 4]); ctx.lineWidth = 1.5; ctx.strokeStyle = "rgba(255,255,207,.9)"; ctx.stroke(); ctx.setLineDash([]);
260:   }
261:   ctx.restore();
262: }
