351: function updateCombat(now) {
352:   const { left, top, cellW, cellH } = layout;
353:   const targets = [...enemies.enemies.values()].filter((enemy) => enemy.alive);
354:   for (const plant of game.plants.values()) {
355:     if (!plant.alive || !plant.exists) {
356:       plant.attackState = "IDLE";
357:       plant.targetId = null;
358:       continue;
359:     }
360:     plant.boardX = (plant.worldPosition.x - left) / cellW;
361:     const target = targets
362:       .filter((enemy) => enemy.row === plant.row && enemy.x > plant.boardX)
363:       .sort((a, b) => a.x - b.x)[0] ?? null;
364:     plant.targetId = target?.id ?? null;
365:     if (!target) {
366:       plant.attackState = "IDLE";
367:       continue;
368:     }
369:     if (now >= plant.nextAttackAt) {
370:       const plantSize = cellW * .83;
371:       projectiles.spawn({
372:         x: plant.worldPosition.x + plantSize * .39,
373:         y: plant.worldPosition.y - plantSize * .565,
374:         row: plant.row,
375:         damage: plant.damage,
376:         speed: plant.projectileSpeed,
377:         ownerId: plant.id,
378:       }, now);
379:       plant.attackState = "SHOOTING";
380:       plant.attackStartedAt = now;
381:       plant.nextAttackAt = now + plant.attackIntervalMs;
382:     } else {
383:       plant.attackState = now - plant.attackStartedAt < 180 ? "SHOOTING" : "AIMING";
384:     }
385:   }
386:   projectiles.update(now, enemies.enemies, { ...layout, width, left, top, cellW, cellH }, enemies);
387: }
