212: function drawSun(sun, now) {
213:   const age = now - sun.spawnedAt;
214:   const fadeIn = Math.min(1, age / SUN_CONFIG.spawnFadeMs);
215:   let alpha = fadeIn;
216:   let scale = 1;
217:   let lift = 0;
218:   if (sun.collected) {
219:     const progress = Math.min(1, (now - sun.collectedAt) / SUN_CONFIG.collectDurationMs);
220:     alpha *= 1 - progress;
221:     scale = 1 + progress * .65;
222:     lift = progress * 24;
223:   } else if (sun.expired) {
224:     alpha *= Math.max(0, 1 - (now - sun.expiredAt) / 300);
225:   }
226:   const hovered = pointer.hoveredSun === sun.id && !sun.collected && !sun.expired;
227:   const radius = SUN_CONFIG.radius * (hovered ? 1.12 : 1) * scale;
228:   const sway = Math.sin(now * .0024 + sun.phase) * (sun.falling ? 2.8 : 1.7);
229:   const pulse = 1 + Math.sin(now * .004 + sun.phase) * .045;
230:   const x = sun.x + sway;
231:   const y = sun.y - lift + Math.sin(now * .0018 + sun.phase) * 1.5;
232:   ctx.save();
233:   ctx.globalAlpha = Math.max(0, alpha);
234:   ctx.translate(x, y);
235:   ctx.scale(pulse, pulse);
236:   ctx.shadowColor = hovered ? "rgba(255,244,95,.95)" : "rgba(255,203,48,.72)";
237:   ctx.shadowBlur = hovered ? 24 : 15;
238:   ctx.fillStyle = "rgba(255,218,74,.25)";
239:   ctx.beginPath(); ctx.arc(0, 0, radius + 5, 0, Math.PI * 2); ctx.fill();
240:   ctx.shadowBlur = 0;
241:   ctx.rotate(now * .00035 + sun.phase);
242:   ctx.lineCap = "round";
243:   for (let i = 0; i < 12; i++) {
244:     ctx.save(); ctx.rotate(i * Math.PI / 6);
245:     ctx.strokeStyle = i % 2 ? "#e89a23" : "#d9851d";
246:     ctx.lineWidth = 3.2;
247:     ctx.beginPath(); ctx.moveTo(0, -radius * .78); ctx.lineTo(0, -radius - (i % 3 === 0 ? 9 : 7)); ctx.stroke();
248:     ctx.restore();
249:   }
250:   const gradient = ctx.createRadialGradient(-radius * .32, -radius * .38, 1, 0, 0, radius);
251:   gradient.addColorStop(0, "#fffeb0"); gradient.addColorStop(.52, "#ffe35a"); gradient.addColorStop(1, "#f6ad2e");
252:   ctx.beginPath(); ctx.arc(0, 0, radius, 0, Math.PI * 2);
253:   ctx.fillStyle = gradient; ctx.fill(); ctx.lineWidth = 2.2; ctx.strokeStyle = "#d68520"; ctx.stroke();
254:   ctx.beginPath(); ctx.arc(0, 0, radius * .57, 0, Math.PI * 2);
255:   ctx.fillStyle = "rgba(255,249,139,.68)"; ctx.fill();
256:   ctx.beginPath(); ctx.ellipse(-radius * .28, -radius * .34, radius * .22, radius * .12, -.55, 0, Math.PI * 2);
257:   ctx.fillStyle = "rgba(255,255,225,.84)"; ctx.fill();
258:   if (hovered) {
259:     ctx.beginPath(); ctx.arc(0, 0, radius + 12, 0, Math.PI * 2);
260:     ctx.setLineDash([3, 4]); ctx.lineWidth = 1.5; ctx.strokeStyle = "rgba(255,255,207,.9)"; ctx.stroke(); ctx.setLineDash([]);
261:   }
