352: function updateCombat(now) {
353:   const { left, top, cellW, cellH } = layout;
354:   const targets = [...enemies.enemies.values()].filter((enemy) => enemy.alive);
355:   for (const plant of game.plants.values()) {
356:     if (!plant.alive || !plant.exists) {
357:       plant.attackState = "IDLE";
358:       plant.targetId = null;
359:       continue;
360:     }
361:     plant.boardX = (plant.worldPosition.x - left) / cellW;
362:     const target = targets
363:       .filter((enemy) => enemy.row === plant.row && enemy.x > plant.boardX)
364:       .sort((a, b) => a.x - b.x)[0] ?? null;
365:     plant.targetId = target?.id ?? null;
366:     if (!target) {
367:       plant.attackState = "IDLE";
368:       continue;
