127: function fillRound(c, x, y, w, h, r, fill, stroke = null, lineWidth = 1) {
128:   roundedRect(c, x, y, w, h, r);
129:   c.fillStyle = fill; c.fill();
130:   if (stroke) { c.lineWidth = lineWidth; c.strokeStyle = stroke; c.stroke(); }
