132: function drawHealthBar(x, y, w, health, maxHealth) {
133:   const ratio = Math.max(0, Math.min(1, health / maxHealth));
134:   fillRound(ctx, x - 1, y - 1, w + 2, 6, 3, "rgba(34,42,28,.8)");
135:   if (ratio > 0) fillRound(ctx, x, y, w * ratio, 4, 2, ratio > .5 ? "#75d34d" : ratio > .25 ? "#f1c84f" : "#e45c4a");
