137: function drawCloud(x, y, scale, alpha = 1) {
138:   ctx.save(); ctx.globalAlpha = alpha; ctx.fillStyle = "#fffbe6";
139:   ctx.beginPath(); ctx.ellipse(x, y, 34 * scale, 12 * scale, 0, 0, Math.PI * 2);
140:   ctx.ellipse(x - 15 * scale, y - 5 * scale, 17 * scale, 13 * scale, 0, 0, Math.PI * 2);
141:   ctx.ellipse(x + 2 * scale, y - 10 * scale, 21 * scale, 17 * scale, 0, 0, Math.PI * 2);
142:   ctx.ellipse(x + 19 * scale, y - 4 * scale, 16 * scale, 12 * scale, 0, 0, Math.PI * 2);
143:   ctx.fill(); ctx.restore();
