146: function drawBackground(time) {
147:   const sky = ctx.createLinearGradient(0, 0, 0, height);
148:   sky.addColorStop(0, "#8dd8e1"); sky.addColorStop(.42, "#d8edbd"); sky.addColorStop(1, "#91c956");
149:   ctx.fillStyle = sky; ctx.fillRect(0, 0, width, height);
150:   drawCloud(width * .15 + Math.sin(time * .00012) * 12, height * .12, .8, .83);
151:   drawCloud(width * .75 - Math.sin(time * .00009) * 17, height * .19, 1.08, .74);
152:   // Distant rounded tree line.
153:   const horizon = layout.top + layout.boardH + 10;
154:   ctx.fillStyle = "#9acc63";
155:   ctx.beginPath(); ctx.moveTo(0, horizon + 16);
156:   for (let x = 0; x <= width + 60; x += 55) ctx.quadraticCurveTo(x + 18, horizon - 27 - (x % 3) * 5, x + 55, horizon + 15);
157:   ctx.lineTo(width, height); ctx.lineTo(0, height); ctx.closePath(); ctx.fill();
158:   // Quiet fence behind the playable lawn.
159:   const fenceY = layout.top - 13;
160:   ctx.fillStyle = "#c98e4c";
161:   for (let x = 10; x < width; x += 52) {
162:     fillRound(ctx, x, fenceY, 8, Math.max(26, layout.boardH + 28), 4, "#bb8248", "#986337", 1);
163:     ctx.beginPath(); ctx.arc(x + 4, fenceY + 4, 4, Math.PI, 0); ctx.fillStyle = "#d8a25c"; ctx.fill();
164:   }
165:   ctx.fillStyle = "#d6a15e";
166:   ctx.fillRect(0, fenceY + 19, width, 8); ctx.fillRect(0, fenceY + layout.boardH + 5, width, 8);
167:   // Soft lawn below the fence.
168:   const lawn = ctx.createLinearGradient(0, horizon, 0, height);
169:   lawn.addColorStop(0, "rgba(143,196,74,.12)"); lawn.addColorStop(1, "rgba(54,128,50,.28)");
170:   ctx.fillStyle = lawn; ctx.fillRect(0, horizon, width, height - horizon);
171:   // Tiny grass strokes, all drawn from simple paths.
172:   ctx.strokeStyle = "rgba(52,119,42,.27)"; ctx.lineWidth = 1.4;
173:   for (let i = 0; i < Math.floor(width / 30); i++) {
174:     const x = (i * 73 + 19) % width; const y = horizon + 22 + (i * 37) % Math.max(35, height - horizon - 24);
175:     ctx.beginPath(); ctx.moveTo(x, y); ctx.quadraticCurveTo(x - 3, y - 8, x - 5, y - 11); ctx.moveTo(x, y); ctx.quadraticCurveTo(x + 3, y - 7, x + 5, y - 10); ctx.stroke();
176:   }
177: }
