197: function drawSunIcon(x, y, radius) {
198:   ctx.save();
199:   ctx.translate(x, y);
200:   ctx.strokeStyle = "#d18021"; ctx.lineWidth = Math.max(1.5, radius * .14); ctx.lineCap = "round";
201:   for (let i = 0; i < 8; i++) {
202:     ctx.rotate(Math.PI / 4); ctx.beginPath(); ctx.moveTo(0, -radius - 2); ctx.lineTo(0, -radius - 6); ctx.stroke();
203:   }
204:   const g = ctx.createRadialGradient(-radius * .3, -radius * .35, 1, 0, 0, radius);
205:   g.addColorStop(0, "#fff99a"); g.addColorStop(1, "#f6b934");
206:   ctx.beginPath(); ctx.arc(0, 0, radius, 0, Math.PI * 2); ctx.fillStyle = g; ctx.fill();
