210: function drawSun(sun, now) {
211:   const age = now - sun.spawnedAt;
212:   const fadeIn = Math.min(1, age / SUN_CONFIG.spawnFadeMs);
213:   let alpha = fadeIn;
214:   let scale = 1;
215:   let lift = 0;
216:   if (sun.collected) {
217:     const progress = Math.min(1, (now - sun.collectedAt) / SUN_CONFIG.collectDurationMs);
218:     alpha *= 1 - progress;
219:     scale = 1 + progress * .65;
220:     lift = progress * 24;
221:   } else if (sun.expired) {
222:     alpha *= Math.max(0, 1 - (now - sun.expiredAt) / 300);
223:   }
224:   const hovered = pointer.hoveredSun === sun.id && !sun.collected && !sun.expired;
225:   const radius = SUN_CONFIG.radius * (hovered ? 1.12 : 1) * scale;
226:   const sway = Math.sin(now * .0024 + sun.phase) * (sun.falling ? 2.8 : 1.7);
227:   const pulse = 1 + Math.sin(now * .004 + sun.phase) * .045;
228:   const x = sun.x + sway;
229:   const y = sun.y - lift + Math.sin(now * .0018 + sun.phase) * 1.5;
230:   ctx.save();
231:   ctx.globalAlpha = Math.max(0, alpha);
232:   ctx.translate(x, y);
233:   ctx.scale(pulse, pulse);
234:   ctx.shadowColor = hovered ? "rgba(255,244,95,.95)" : "rgba(255,203,48,.72)";
235:   ctx.shadowBlur = hovered ? 24 : 15;
236:   ctx.fillStyle = "rgba(255,218,74,.25)";
237:   ctx.beginPath(); ctx.arc(0, 0, radius + 5, 0, Math.PI * 2); ctx.fill();
238:   ctx.shadowBlur = 0;
239:   ctx.rotate(now * .00035 + sun.phase);
240:   ctx.lineCap = "round";
241:   for (let i = 0; i < 12; i++) {
242:     ctx.save(); ctx.rotate(i * Math.PI / 6);
243:     ctx.strokeStyle = i % 2 ? "#e89a23" : "#d9851d";
244:     ctx.lineWidth = 3.2;
245:     ctx.beginPath(); ctx.moveTo(0, -radius * .78); ctx.lineTo(0, -radius - (i % 3 === 0 ? 9 : 7)); ctx.stroke();
246:     ctx.restore();
247:   }
248:   const gradient = ctx.createRadialGradient(-radius * .32, -radius * .38, 1, 0, 0, radius);
249:   gradient.addColorStop(0, "#fffeb0"); gradient.addColorStop(.52, "#ffe35a"); gradient.addColorStop(1, "#f6ad2e");
250:   ctx.beginPath(); ctx.arc(0, 0, radius, 0, Math.PI * 2);
251:   ctx.fillStyle = gradient; ctx.fill(); ctx.lineWidth = 2.2; ctx.strokeStyle = "#d68520"; ctx.stroke();
252:   ctx.beginPath(); ctx.arc(0, 0, radius * .57, 0, Math.PI * 2);
253:   ctx.fillStyle = "rgba(255,249,139,.68)"; ctx.fill();
254:   ctx.beginPath(); ctx.ellipse(-radius * .28, -radius * .34, radius * .22, radius * .12, -.55, 0, Math.PI * 2);
255:   ctx.fillStyle = "rgba(255,255,225,.84)"; ctx.fill();
256:   if (hovered) {
257:     ctx.beginPath(); ctx.arc(0, 0, radius + 12, 0, Math.PI * 2);
258:     ctx.setLineDash([3, 4]); ctx.lineWidth = 1.5; ctx.strokeStyle = "rgba(255,255,207,.9)"; ctx.stroke(); ctx.setLineDash([]);
259:   }
260:   ctx.restore();
261: }
