350: function updateCombat(now) {
351:   const { left, top, cellW, cellH } = layout;
352:   const targets = [...enemies.enemies.values()].filter((enemy) => enemy.alive);
353:   for (const plant of game.plants.values()) {
354:     if (!plant.alive || !plant.exists) {
355:       plant.attackState = "IDLE";
356:       plant.targetId = null;
357:       continue;
358:     }
359:     plant.boardX = (plant.worldPosition.x - left) / cellW;
360:     const target = targets
361:       .filter((enemy) => enemy.row === plant.row && enemy.x > plant.boardX)
362:       .sort((a, b) => a.x - b.x)[0] ?? null;
363:     plant.targetId = target?.id ?? null;
364:     if (!target) {
365:       plant.attackState = "IDLE";
366:       continue;
367:     }
368:     if (now >= plant.nextAttackAt) {
369:       const plantSize = cellW * .83;
370:       projectiles.spawn({
371:         x: plant.worldPosition.x + plantSize * .39,
372:         y: plant.worldPosition.y - plantSize * .565,
373:         row: plant.row,
374:         damage: plant.damage,
375:         speed: plant.projectileSpeed,
376:         ownerId: plant.id,
377:       }, now);
378:       plant.attackState = "SHOOTING";
379:       plant.attackStartedAt = now;
380:       plant.nextAttackAt = now + plant.attackIntervalMs;
381:     } else {
382:       plant.attackState = now - plant.attackStartedAt < 180 ? "SHOOTING" : "AIMING";
383:     }
384:   }
385:   projectiles.update(now, enemies.enemies, { ...layout, width, left, top, cellW, cellH }, enemies);
386: }
