392:   ctx.shadowColor = "rgba(38,77,25,.35)"; ctx.shadowBlur = 5; ctx.shadowOffsetY = 2;
393:   const glow = ctx.createRadialGradient(-2, -3, 1, 0, 0, projectile.radius * pulse);
394:   glow.addColorStop(0, "#e4ff8a"); glow.addColorStop(.55, "#83d63e"); glow.addColorStop(1, "#438a2c");
395:   ctx.beginPath(); ctx.arc(0, 0, projectile.radius * pulse, 0, Math.PI * 2);
396:   ctx.fillStyle = glow; ctx.fill(); ctx.lineWidth = 1.5; ctx.strokeStyle = "#315d25"; ctx.stroke();
397:   ctx.shadowColor = "transparent";
398:   ctx.beginPath(); ctx.ellipse(-projectile.radius * .3, -projectile.radius * .35, projectile.radius * .22, projectile.radius * .12, -.5, 0, Math.PI * 2);
399:   ctx.fillStyle = "rgba(255,255,220,.8)"; ctx.fill();
400:   ctx.restore();
401: }
