403: function drawBoard(now) {
404:   const { left, top, cellW, cellH, boardW, boardH } = layout;
405:   ctx.save();
406:   ctx.shadowColor = "rgba(46,66,34,.28)"; ctx.shadowBlur = 16; ctx.shadowOffsetY = 8;
407:   fillRound(ctx, left - 12, top - 12, boardW + 24, boardH + 24, 16, "#a96e39", "#754a2c", 3);
408:   ctx.shadowColor = "transparent";
409:   const frame = ctx.createLinearGradient(0, top - 12, 0, top + boardH + 12);
410:   frame.addColorStop(0, "#d49a55"); frame.addColorStop(.5, "#bd7f41"); frame.addColorStop(1, "#99602f");
411:   fillRound(ctx, left - 8, top - 8, boardW + 16, boardH + 16, 11, frame, "#e4b46f", 2);
412:   // These cells are the sole source of row/column hit-testing and occupancy visuals.
413:   for (let row = 0; row < game.rows; row++) {
414:     for (let column = 0; column < game.columns; column++) {
415:       const x = left + column * cellW; const y = top + row * cellH;
416:       const plant = game.getAt(row, column);
417:       const hovered = state.hoveredCell?.row === row && state.hoveredCell?.column === column;
418:       const shade = (row + column) % 2 === 0;
419:       fillRound(ctx, x + 1, y + 1, cellW - 2, cellH - 2, 4, shade ? "#88c750" : "#7fbd48", "rgba(49,101,39,.33)", 1);
420:       ctx.strokeStyle = "rgba(238,255,177,.15)"; ctx.lineWidth = 1;
421:       ctx.beginPath(); ctx.moveTo(x + 6, y + cellH - 6); ctx.lineTo(x + cellW - 7, y + 7); ctx.stroke();
422:       if (state.selected) {
423:         ctx.fillStyle = plant ? "rgba(193,61,44,.20)" : "rgba(220,255,161,.15)";
424:         ctx.fillRect(x + 2, y + 2, cellW - 4, cellH - 4);
425:         ctx.strokeStyle = plant ? "rgba(163,48,38,.68)" : "rgba(242,255,193,.8)";
426:         ctx.lineWidth = plant ? 2 : 1.3; ctx.setLineDash(plant ? [4, 3] : [5, 5]);
427:         ctx.strokeRect(x + 4, y + 4, cellW - 8, cellH - 8); ctx.setLineDash([]);
428:       }
429:       if (hovered) {
430:         ctx.strokeStyle = state.selected && plant ? "#cf5141" : "#fff39a";
431:         ctx.lineWidth = 3; ctx.strokeRect(x + 3, y + 3, cellW - 6, cellH - 6);
432:       }
433:     }
434:   }
435:   ctx.restore();
436: 
437:   // Plant data is rendered independently from occupancy and placement rules.
438:   for (const plant of game.plants.values()) {
439:     if (!plant.exists) continue;
440:     const target = plant.targetId ? enemies.get(plant.targetId) : null;
441:     const plantSize = cellW * .83;
442:     const muzzleX = plant.worldPosition.x + plantSize * .39;
443:     const muzzleY = plant.worldPosition.y - plantSize * .565;
444:     const targetX = target ? left + target.x * cellW : muzzleX + cellW;
445:     const targetY = target ? top + (target.row + .88) * cellH - cellH * .96 * .55 : muzzleY;
446:     drawPeashooter(ctx, plant.worldPosition.x, plant.worldPosition.y, plantSize, now, {
447:       age: now - plant.animationStartedAt,
448:       disappearing: plant.animationState === "disappearing",
449:       attackState: plant.attackState,
450:       aimAngle: plant.targetId ? Math.atan2(targetY - muzzleY, targetX - muzzleX) : 0,
451:     });
452:     if (plant.alive) drawHealthBar(plant.worldPosition.x - cellW * .2, plant.worldPosition.y - plantSize * .96, cellW * .4, plant.health, plant.maxHealth);
453:   }
454:   // Enemies are drawn above plants so a clone approaching an obstacle stays legible.
455:   for (const enemy of enemies.enemies.values()) {
456:     if (enemy.state === "DEAD") continue;
457:     const enemyX = left + enemy.x * cellW;
458:     const enemyY = top + (enemy.row + .88) * cellH;
459:     drawBasicClone(ctx, enemyX, enemyY, cellH * .96, now, enemy);
460:     drawHealthBar(enemyX - cellH * .21, enemyY - cellH * .98, cellH * .42, enemy.health, enemy.maxHealth);
461:     if (enemy.state === "DETECTING" || enemy.state === "ATTACKING") {
462:       const label = enemy.state === "DETECTING" ? "¡PLANTA!" : "DETENIDO";
463:       ctx.save();
464:       ctx.font = `900 ${layout.compact ? 8 : 9}px Trebuchet MS, sans-serif`;
465:       ctx.textAlign = "center"; ctx.textBaseline = "middle";
466:       const labelW = ctx.measureText(label).width + 12;
467:       fillRound(ctx, enemyX - labelW / 2, enemyY - cellH * .99, labelW, 16, 8,
468:         enemy.state === "ATTACKING" ? "rgba(116,65,48,.9)" : "rgba(69,83,47,.88)", "rgba(255,244,206,.8)", 1);
469:       ctx.fillStyle = "#fff4d5"; ctx.fillText(label, enemyX, enemyY - cellH * .99 + 8);
470:       ctx.restore();
