import assert from 'node:assert/strict';
import { TEST_LEVEL, validateLevel } from './src/wave-config.js';
import { WaveManager, WAVE_STATES } from './src/wave-manager.js';

assert.equal(validateLevel(TEST_LEVEL), true);
assert.deepEqual(TEST_LEVEL.waves.map(({ count }) => count), [2, 3, 4, 5, 8]);
const spawned = new Map();
let nextId = 1;
const enemySystem = { get: (id) => spawned.get(id) ?? null };
const manager = new WaveManager(TEST_LEVEL, {
  enemySystem,
  spawnEnemy: (type, row, x, overrides, now) => {
    const enemy = { id: `test-${nextId++}`, type, row, x, alive: true, ...overrides, spawnedAt: now };
    spawned.set(enemy.id, enemy);
    return { ok: true, enemy };
  },
});
manager.start(0);
assert.equal(manager.snapshot().remainingTimeMs, 10000);
manager.update(9999);
assert.equal(spawned.size, 0);
manager.pause(9999);
manager.update(30000);
assert.equal(spawned.size, 0);
manager.resume(30000);
manager.update(10000);
let now = 10001;
while (manager.state !== WAVE_STATES.COMPLETED && manager.state !== WAVE_STATES.DEFEAT && now < 2000000) {
  manager.update(now);
  for (const id of [...manager.aliveIds]) spawned.get(id).alive = false;
  now += 3001;
}
assert.equal(manager.state, WAVE_STATES.COMPLETED);
assert.equal(manager.totalSpawned, 22);
assert.equal(spawned.size, 22);
console.log('Wave flow passed: preparation, pause, all 22 exact spawns, completion.');
EOF

