mkdir -p /tmp/opencode/wave-smoke/src && cp src/wave-config.js src/wave-manager.js src/enemy-system.js /tmp/opencode/wave-smoke/src/ && printf '{"type":"module"}\n' > /tmp/opencode/wave-smoke/package.json && cat > /tmp/opencode/wave-smoke/smoke.mjs <<'EOF'
import assert from 'node:assert/strict';
import { WaveManager, WAVE_STATES } from './src/wave-manager.js';
import { EnemySystem } from './src/enemy-system.js';
import { TEST_LEVEL } from './src/wave-config.js';

let now = 0;
const enemies = new EnemySystem(5);
const spawnedPerWave = [];
let activeWave = 1;
const manager = new WaveManager(TEST_LEVEL, {
  enemySystem: enemies,
  spawnEnemy: (...args) => {
    const result = enemies.spawn(...args);
    if (result.ok) spawnedPerWave[activeWave - 1] = (spawnedPerWave[activeWave - 1] ?? 0) + 1;
    return result;
  },
});
manager.start(now);
assert.equal(manager.state, WAVE_STATES.COUNTDOWN);
manager.update(5000);
const beforePause = manager.snapshot(5000).remainingTimeMs;
manager.pause(5000);
manager.update(20000);
assert.equal(manager.snapshot(20000).remainingTimeMs, beforePause);
manager.resume(20000);
now = 20000;
let guard = 0;
while (manager.state !== WAVE_STATES.COMPLETED && guard++ < 500) {
  now += 1000;
  manager.update(now);
  for (const id of [...manager.aliveIds]) enemies.damage(id, 100000, now);
  manager.update(now + 1);
  activeWave = manager.currentWave || activeWave;
}
assert.equal(manager.state, WAVE_STATES.COMPLETED, `did not complete (state=${manager.state}, wave=${manager.currentWave})`);
assert.deepEqual(spawnedPerWave, [2, 3, 4, 5, 8]);
